import re

from taf.hw.rf_attenuator.devices.hytem.hytem import Hytem


class HytemV5(Hytem):

    def _provide_correct_att_format(self, att_value):
        """Converts given numeric value to a three digit string, where last digit is a decimal part.
        Throws exception if decimal part length exceeds one digit or whole number length exceeds three digits.
        If whole number length is below three digits, value is topped up with zeros added on the left side.
        Example:
              0.01  -> 0001
                 1  -> 0100
                10  -> 1000
              93.5  -> 9350
        :param att_value - integer or float with one decimal place
        :return: attenuation value in a format suitable for Hytem rf_attenuator (str) """
        if isinstance(att_value, float):
            att_string = str(att_value)
            regex_determine_decimal_part_length = re.compile(r'(\d+\.\d)(\d*)')
            match = re.match(regex_determine_decimal_part_length, att_string)
            if len(match.group(2)) > 1:
                raise ValueError('Decimal part too long in provided value {}.'
                                 ' Only two decimal place is allowed'.format(att_value))
            att_string = str(int(att_value * 100))
        elif isinstance(att_value, int):
            att_value *= 100
            att_string = str(att_value)
        else:
            raise TypeError("Wrong type of value provided: {}.".format(type(att_value)))
        att_string = self._ensure_attenuation_value_string_has_correct_length(att_string)
        return att_string

    def _ensure_attenuation_value_string_has_correct_length(self, att_string):
        """ Fits given string to three characters format.
        Examples:
              0.01  -> 0001
                 1  -> 0100
                10  -> 1000
              93.5  -> 9350
              11111 -> Throws exception
        :param att_string - attenuation value in string format
        :return: attenuation value in a three-digits format (str) """
        if len(att_string) > 4:
            raise ValueError("Expected value 1 to 4 characters long, but got {}"
                             "(last digit is decimal part)".format(att_string))
        else:
            while len(att_string) < 4:
                att_string = '0' + att_string
        return att_string
